import 'pomodoro.dart';
import '../core/i18n.dart';

enum FocusLeaderboardScope { friends, global }

/// Explicit provenance for room copy generated by the app's built-in catalog.
/// Room IDs or matching text alone never establish this provenance.
enum FocusRoomBuiltinKind {
  deepWork,
  examSprint,
  reading;

  String get storageCode => switch (this) {
    deepWork => 'deep_work',
    examSprint => 'exam_sprint',
    reading => 'reading',
  };

  String get roomId => switch (this) {
    deepWork => 'deep_work_room',
    examSprint => 'exam_sprint_room',
    reading => 'reading_room',
  };

  String nameFor(AppLocale locale) => switch (this) {
    deepWork => locale == AppLocale.en ? 'Deep work room' : '深度工作自习室',
    examSprint => locale == AppLocale.en ? 'Exam preparation room' : '考试冲刺自习室',
    reading => locale == AppLocale.en ? 'Reading room' : '阅读自习室',
  };

  String descriptionFor(AppLocale locale) => switch (this) {
    deepWork =>
      locale == AppLocale.en
          ? 'For writing, development, and demanding mental work.'
          : '适合写作、开发和高强度脑力任务。',
    examSprint =>
      locale == AppLocale.en
          ? 'Make weekly progress on practice questions, memorization, and revision.'
          : '按周目标推进刷题、背诵和复习。',
    reading =>
      locale == AppLocale.en
          ? 'A quiet space for reading, papers, and organizing knowledge.'
          : '给阅读、论文和知识整理留一张安静桌子。',
  };

  /// Validates an explicit marker; never infers one from matching raw content.
  bool matchesContent(FocusRoom room) =>
      room.id == roomId &&
      room.name == nameFor(AppLocale.zh) &&
      room.description == descriptionFor(AppLocale.zh);

  static FocusRoomBuiltinKind? fromStorageCode(Object? value) {
    for (final kind in values) {
      if (value == kind.storageCode) {
        return kind;
      }
    }
    return null;
  }
}

/// Runtime provenance for app-generated ranking explanations.
/// Server explanations remain literal when no reason bit is set.
enum FocusFlagReasonCode {
  weeklyCap,
  longSessionCap,
  dailyCap,
  futureSessionIgnored,
  remoteCorrectionFallback;

  int get mask => 1 << index;

  String labelFor(AppLocale locale) {
    final isEn = locale == AppLocale.en;
    return switch (this) {
      weeklyCap =>
        isEn ? 'Weekly credited time exceeded the limit' : '超过每周有效时长上限',
      longSessionCap =>
        isEn ? 'Sessions over 4 hours were capped' : '单次专注超过 4 小时已封顶',
      dailyCap =>
        isEn
            ? 'Daily credited focus over 12 hours was capped'
            : '单日有效专注超过 12 小时已封顶',
      futureSessionIgnored =>
        isEn ? 'Future focus records were ignored' : '忽略未来专注记录',
      remoteCorrectionFallback =>
        isEn ? 'The server adjusted unusual focus time' : '服务端已校正异常时长',
    };
  }
}

String? _generatedFlagReason(int reasons, AppLocale locale) {
  final labels = [
    for (final reason in FocusFlagReasonCode.values)
      if ((reasons & reason.mask) != 0) reason.labelFor(locale),
  ];
  return labels.isEmpty
      ? null
      : labels.join(locale == AppLocale.en ? '; ' : '；');
}

class FocusRoomMemberSeed {
  final String id;
  final String name;
  final int weeklySeconds;
  final int sessionCount;

  const FocusRoomMemberSeed({
    required this.id,
    required this.name,
    required this.weeklySeconds,
    required this.sessionCount,
  });

  Map<String, dynamic> toJson() => {
    'id': id,
    'name': name,
    'weeklySeconds': weeklySeconds,
    'sessionCount': sessionCount,
  };

  factory FocusRoomMemberSeed.fromJson(Map<String, dynamic> json) =>
      FocusRoomMemberSeed(
        id: json['id']?.toString() ?? '',
        name: json['name']?.toString() ?? '同学',
        weeklySeconds: (json['weeklySeconds'] as num?)?.round() ?? 0,
        sessionCount: (json['sessionCount'] as num?)?.round() ?? 0,
      );
}

class FocusRoom {
  final String id;
  final String name;
  final String description;
  final int weeklyTargetSeconds;
  final int accentColor;
  final List<FocusRoomMemberSeed> members;
  final DateTime createdAt;
  final FocusRoomBuiltinKind? _builtinKind;

  const FocusRoom({
    required this.id,
    required this.name,
    required this.description,
    required this.weeklyTargetSeconds,
    required this.accentColor,
    required this.members,
    required this.createdAt,
    FocusRoomBuiltinKind? builtinKind,
  }) : _builtinKind = builtinKind;

  FocusRoomBuiltinKind? get builtinKind =>
      _builtinKind?.matchesContent(this) == true ? _builtinKind : null;

  String nameFor(AppLocale locale) => builtinKind?.nameFor(locale) ?? name;

  String descriptionFor(AppLocale locale) =>
      builtinKind?.descriptionFor(locale) ?? description;

  /// Keeps raw room data intact when restoring trusted local catalog metadata.
  FocusRoom withBuiltinKind(FocusRoomBuiltinKind kind) => FocusRoom(
    id: id,
    name: name,
    description: description,
    weeklyTargetSeconds: weeklyTargetSeconds,
    accentColor: accentColor,
    members: members,
    createdAt: createdAt,
    builtinKind: kind,
  );

  Map<String, dynamic> toJson() => {
    'id': id,
    'name': name,
    'description': description,
    'weeklyTargetSeconds': weeklyTargetSeconds,
    'accentColor': accentColor,
    'members': members.map((m) => m.toJson()).toList(),
    'createdAt': createdAt.toIso8601String(),
  };

  factory FocusRoom.fromJson(Map<String, dynamic> json) => FocusRoom(
    id: json['id']?.toString() ?? '',
    name: json['name']?.toString() ?? '专注自习室',
    description: json['description']?.toString() ?? '',
    weeklyTargetSeconds: (json['weeklyTargetSeconds'] as num?)?.round() ?? 0,
    accentColor: (json['accentColor'] as num?)?.round() ?? 0xFFE53935,
    members:
        (json['members'] as List?)
            ?.whereType<Map>()
            .map((m) => FocusRoomMemberSeed.fromJson(Map.from(m)))
            .toList() ??
        const <FocusRoomMemberSeed>[],
    createdAt:
        DateTime.tryParse(json['createdAt']?.toString() ?? '') ??
        DateTime.fromMillisecondsSinceEpoch(0),
  );
}

class FocusRoomRankingEntry {
  final String id;
  final String name;
  final int weeklySeconds;
  final int rawWeeklySeconds;
  final int sessionCount;
  final bool isCurrentUser;
  final bool online;
  final bool active;
  final bool flagged;
  final String? _flagReason;
  final int generatedFlagReasons;
  final int rank;
  final DateTime? lastSeenAt;

  const FocusRoomRankingEntry({
    required this.id,
    required this.name,
    required this.weeklySeconds,
    this.rawWeeklySeconds = 0,
    required this.sessionCount,
    required this.isCurrentUser,
    this.online = false,
    this.active = true,
    this.flagged = false,
    String? flagReason,
    this.generatedFlagReasons = 0,
    required this.rank,
    this.lastSeenAt,
  }) : _flagReason = flagReason;

  String? get flagReason => flagReasonFor(I18n.current);

  String? flagReasonFor(AppLocale locale) =>
      _generatedFlagReason(generatedFlagReasons, locale) ?? _flagReason;

  int get weeklyMinutes => weeklySeconds ~/ 60;
  int get rawWeeklyMinutes =>
      rawWeeklySeconds <= 0 ? weeklyMinutes : rawWeeklySeconds ~/ 60;
}

class FocusRoomRanking {
  final FocusRoom room;
  final List<FocusRoomRankingEntry> entries;
  final int userWeeklySeconds;
  final int userSessionCount;
  final DateTime weekStart;
  final DateTime weekEnd;
  final bool remote;
  final int onlineCount;
  final DateTime? updatedAt;

  const FocusRoomRanking({
    required this.room,
    required this.entries,
    required this.userWeeklySeconds,
    required this.userSessionCount,
    required this.weekStart,
    required this.weekEnd,
    this.remote = false,
    this.onlineCount = 0,
    this.updatedAt,
  });

  int get userWeeklyMinutes => userWeeklySeconds ~/ 60;
  int get totalWeeklySeconds =>
      entries.fold(0, (sum, entry) => sum + entry.weeklySeconds);
  int get targetProgressPercent => room.weeklyTargetSeconds <= 0
      ? 0
      : ((userWeeklySeconds / room.weeklyTargetSeconds) * 100)
            .clamp(0, 999)
            .round();
}

class FocusSocialRanking {
  final FocusLeaderboardScope scope;
  final List<FocusRoomRankingEntry> entries;
  final DateTime weekStart;
  final DateTime weekEnd;
  final int suspiciousEntryCount;
  final bool remote;
  final int onlineCount;
  final DateTime? updatedAt;

  const FocusSocialRanking({
    required this.scope,
    required this.entries,
    required this.weekStart,
    required this.weekEnd,
    required this.suspiciousEntryCount,
    this.remote = false,
    this.onlineCount = 0,
    this.updatedAt,
  });

  String get title => titleFor(I18n.current);

  String titleFor(AppLocale locale) => switch (scope) {
    FocusLeaderboardScope.friends =>
      locale == AppLocale.en ? 'Friends focus ranking' : '好友专注榜',
    FocusLeaderboardScope.global =>
      locale == AppLocale.en ? 'Global focus ranking' : '全局专注榜',
  };

  String get subtitle => subtitleFor(I18n.current);

  String subtitleFor(AppLocale locale) => switch (scope) {
    FocusLeaderboardScope.friends =>
      locale == AppLocale.en
          ? 'Ranked by friends’ credited focus time this week'
          : '按好友本周有效专注时长排名',
    FocusLeaderboardScope.global =>
      locale == AppLocale.en
          ? 'Ranked by credited focus time across all users this week'
          : '按全站本周有效专注时长排名',
  };
}

DateTime focusRoomWeekStart(DateTime now) {
  final day = DateTime(now.year, now.month, now.day);
  return day.subtract(Duration(days: day.weekday - DateTime.monday));
}

const int _maxCreditedSessionSeconds = 4 * 60 * 60;
const int _maxCreditedDailySeconds = 12 * 60 * 60;

FocusRoomRanking buildFocusRoomRanking({
  required FocusRoom room,
  required Iterable<PomodoroSession> sessions,
  required DateTime now,
  String currentUserName = '我',
}) {
  final start = focusRoomWeekStart(now);
  final end = start.add(const Duration(days: 7));
  final roomSessions = sessions.where(
    (s) =>
        s.type == PomodoroType.focus &&
        s.focusRoomId == room.id &&
        !s.startTime.isBefore(start) &&
        s.startTime.isBefore(end),
  );
  final userScore = _scoreSessionsWithAntiCheat(
    roomSessions,
    now: now,
    weekStart: start,
    weekEnd: end,
  );
  final rawEntries =
      <FocusRoomRankingEntry>[
        FocusRoomRankingEntry(
          id: 'current_user',
          name: currentUserName,
          weeklySeconds: userScore.creditedSeconds,
          rawWeeklySeconds: userScore.rawSeconds,
          sessionCount: userScore.sessionCount,
          isCurrentUser: true,
          online: true,
          flagged: userScore.flagged,
          flagReason: userScore.flagReason,
          generatedFlagReasons: userScore.generatedFlagReasons,
          rank: 0,
        ),
        ...room.members.map(
          (m) => FocusRoomRankingEntry(
            id: m.id,
            name: m.name,
            weeklySeconds: m.weeklySeconds,
            rawWeeklySeconds: m.weeklySeconds,
            sessionCount: m.sessionCount,
            isCurrentUser: false,
            online: false,
            rank: 0,
          ),
        ),
      ]..sort((a, b) {
        final bySeconds = b.weeklySeconds.compareTo(a.weeklySeconds);
        if (bySeconds != 0) return bySeconds;
        final bySessions = b.sessionCount.compareTo(a.sessionCount);
        if (bySessions != 0) return bySessions;
        return a.name.compareTo(b.name);
      });

  final ranked = <FocusRoomRankingEntry>[];
  for (var i = 0; i < rawEntries.length; i++) {
    final entry = rawEntries[i];
    ranked.add(
      FocusRoomRankingEntry(
        id: entry.id,
        name: entry.name,
        weeklySeconds: entry.weeklySeconds,
        rawWeeklySeconds: entry.rawWeeklySeconds,
        sessionCount: entry.sessionCount,
        isCurrentUser: entry.isCurrentUser,
        online: entry.online,
        active: entry.active,
        flagged: entry.flagged,
        flagReason: entry.flagReason,
        generatedFlagReasons: entry.generatedFlagReasons,
        rank: i + 1,
        lastSeenAt: entry.lastSeenAt,
      ),
    );
  }

  return FocusRoomRanking(
    room: room,
    entries: ranked,
    userWeeklySeconds: userScore.creditedSeconds,
    userSessionCount: userScore.sessionCount,
    weekStart: start,
    weekEnd: end,
  );
}

FocusSocialRanking buildFocusSocialRanking({
  required FocusLeaderboardScope scope,
  required Iterable<PomodoroSession> sessions,
  required Iterable<FocusRoomMemberSeed> seedMembers,
  required DateTime now,
  String currentUserName = '我',
}) {
  final start = focusRoomWeekStart(now);
  final end = start.add(const Duration(days: 7));
  final userSessions = sessions.where(
    (s) =>
        s.type == PomodoroType.focus &&
        !s.startTime.isBefore(start) &&
        s.startTime.isBefore(end),
  );
  final userScore = _scoreSessionsWithAntiCheat(
    userSessions,
    now: now,
    weekStart: start,
    weekEnd: end,
  );
  final rawEntries =
      <FocusRoomRankingEntry>[
        FocusRoomRankingEntry(
          id: 'current_user',
          name: currentUserName,
          weeklySeconds: userScore.creditedSeconds,
          rawWeeklySeconds: userScore.rawSeconds,
          sessionCount: userScore.sessionCount,
          isCurrentUser: true,
          online: true,
          flagged: userScore.flagged,
          flagReason: userScore.flagReason,
          generatedFlagReasons: userScore.generatedFlagReasons,
          rank: 0,
        ),
        ...seedMembers.map((m) {
          final seeded = _scoreSeedMember(m);
          return FocusRoomRankingEntry(
            id: m.id,
            name: m.name,
            weeklySeconds: seeded.creditedSeconds,
            rawWeeklySeconds: seeded.rawSeconds,
            sessionCount: seeded.sessionCount,
            isCurrentUser: false,
            online: false,
            flagged: seeded.flagged,
            flagReason: seeded.flagReason,
            generatedFlagReasons: seeded.generatedFlagReasons,
            rank: 0,
          );
        }),
      ]..sort((a, b) {
        final bySeconds = b.weeklySeconds.compareTo(a.weeklySeconds);
        if (bySeconds != 0) return bySeconds;
        final bySessions = b.sessionCount.compareTo(a.sessionCount);
        if (bySessions != 0) return bySessions;
        return a.name.compareTo(b.name);
      });

  final ranked = <FocusRoomRankingEntry>[];
  for (var i = 0; i < rawEntries.length; i++) {
    final entry = rawEntries[i];
    ranked.add(
      FocusRoomRankingEntry(
        id: entry.id,
        name: entry.name,
        weeklySeconds: entry.weeklySeconds,
        rawWeeklySeconds: entry.rawWeeklySeconds,
        sessionCount: entry.sessionCount,
        isCurrentUser: entry.isCurrentUser,
        online: entry.online,
        active: entry.active,
        flagged: entry.flagged,
        flagReason: entry.flagReason,
        generatedFlagReasons: entry.generatedFlagReasons,
        rank: i + 1,
        lastSeenAt: entry.lastSeenAt,
      ),
    );
  }

  return FocusSocialRanking(
    scope: scope,
    entries: ranked,
    weekStart: start,
    weekEnd: end,
    suspiciousEntryCount: ranked.where((entry) => entry.flagged).length,
  );
}

class _FocusAntiCheatScore {
  final int rawSeconds;
  final int creditedSeconds;
  final int sessionCount;
  final bool flagged;
  final int generatedFlagReasons;

  const _FocusAntiCheatScore({
    required this.rawSeconds,
    required this.creditedSeconds,
    required this.sessionCount,
    required this.flagged,
    this.generatedFlagReasons = 0,
  });

  String? get flagReason =>
      _generatedFlagReason(generatedFlagReasons, AppLocale.zh);
}

_FocusAntiCheatScore _scoreSeedMember(FocusRoomMemberSeed member) {
  final creditedSeconds = member.weeklySeconds
      .clamp(0, _maxCreditedDailySeconds * 7)
      .toInt();
  final flagged = creditedSeconds != member.weeklySeconds;
  return _FocusAntiCheatScore(
    rawSeconds: member.weeklySeconds,
    creditedSeconds: creditedSeconds,
    sessionCount: member.sessionCount,
    flagged: flagged,
    generatedFlagReasons: flagged ? FocusFlagReasonCode.weeklyCap.mask : 0,
  );
}

_FocusAntiCheatScore _scoreSessionsWithAntiCheat(
  Iterable<PomodoroSession> sessions, {
  required DateTime now,
  required DateTime weekStart,
  required DateTime weekEnd,
}) {
  final daily = <DateTime, int>{};
  var rawSeconds = 0;
  var creditedSeconds = 0;
  var sessionCount = 0;
  var clippedLongSession = false;
  var clippedDailyCap = false;
  var futureSession = false;

  for (final session in sessions) {
    if (session.startTime.isAfter(now)) {
      futureSession = true;
      continue;
    }
    if (session.startTime.isBefore(weekStart) ||
        !session.startTime.isBefore(weekEnd)) {
      continue;
    }
    sessionCount++;
    final raw = session.durationSeconds < 0 ? 0 : session.durationSeconds;
    rawSeconds += raw;
    final sessionCredit = raw.clamp(0, _maxCreditedSessionSeconds).toInt();
    if (sessionCredit != raw) clippedLongSession = true;
    final day = DateTime(
      session.startTime.year,
      session.startTime.month,
      session.startTime.day,
    );
    final alreadyCredited = daily[day] ?? 0;
    final remaining = _maxCreditedDailySeconds - alreadyCredited;
    if (remaining <= 0) {
      clippedDailyCap = true;
      continue;
    }
    final credited = sessionCredit.clamp(0, remaining).toInt();
    if (credited != sessionCredit) clippedDailyCap = true;
    daily[day] = alreadyCredited + credited;
    creditedSeconds += credited;
  }

  final reasons =
      (clippedLongSession ? FocusFlagReasonCode.longSessionCap.mask : 0) |
      (clippedDailyCap ? FocusFlagReasonCode.dailyCap.mask : 0) |
      (futureSession ? FocusFlagReasonCode.futureSessionIgnored.mask : 0);
  return _FocusAntiCheatScore(
    rawSeconds: rawSeconds,
    creditedSeconds: creditedSeconds,
    sessionCount: sessionCount,
    flagged: reasons != 0,
    generatedFlagReasons: reasons,
  );
}
